		/** 
		 * Tests creating a new Routing.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Routing");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Routing" );

			try {            
				Routing entity = RoutingService.getRoutingInstance().createRouting( generateNewEntity() );
				thePrimaryKey = entity.getRoutingId();
				LOGGER.info( "-- Successfully created a Routing with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Routing. 
		 */
		public Routing testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Routing" );

			Routing entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Routing with primary key" );
			msg.append( thePrimaryKey );
			
			RoutingFetchOneSummary fetchOneSummary = new RoutingFetchOneSummary( thePrimaryKey );

			try {
				entity = RoutingService.getRoutingInstance().getRouting( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Routing " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Routing.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Routing." );

			StringBuilder msg = new StringBuilder( "Failed to update a Routing : " );        
			Routing entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Routing." );

				// for use later on...
				thePrimaryKey = entity.getRoutingId();

				RoutingService proxy = RoutingService.getRoutingInstance();            
				proxy.updateRouting( entity );   

				LOGGER.info( "-- Successfully saved Routing - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Routing.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Routing." );

			try{
			    Routing entity = testRead(); 
				RoutingService.getRoutingInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Routing with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Routing with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Routings.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Routings:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Routing : " );        
			List<Routing> collection  = null;

			try {
				// call the static get method on the RoutingService
				collection = RoutingService.getRoutingInstance().getAllRouting();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Routing entity = null;            
					Iterator<Routing> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getRoutingId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

